<template><div class="space-y-6"><CPageHeader title="Pagos en línea" description="Cobros y reembolsos confirmados por la pasarela. Los registros demo no representan dinero real." /><p v-if="error" class="operation-error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><CCard><CButton variant="secondary" :loading="busy" @click="load">Actualizar</CButton><div class="operation-scroll"><table class="operation-table"><thead><tr><th>Reserva</th><th>Pasarela</th><th>Importe</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td><NuxtLink :to="`/reservations/${p.reservation_id}`">#{{ p.reservation_id }}</NuxtLink></td><td>{{ p.provider==='demo'?'DEMO · sin dinero real':p.provider }}</td><td>{{ p.amount }} {{ p.currency }}</td><td>{{ states[p.status] || p.status }}</td><td><CButton v-if="['paid','refund_pending'].includes(p.status)" variant="secondary" size="sm" :disabled="busy" @click="selected=p">Reembolsar</CButton></td></tr></tbody></table></div><p v-if="!payments.length">Todavía no hay pagos en línea.</p></CCard><CModal :is-open="!!selected" title="Reembolsar pago" @close="selected=undefined"><p v-if="selected">Se devolverá el importe completo de {{ selected.amount }} {{ selected.currency }} por el mismo medio. {{ selected.provider==='demo'?'Es una simulación sin dinero real.':'La operación se enviará a la pasarela.' }}</p><template #footer><CButton variant="secondary" :disabled="busy" @click="selected=undefined">Volver</CButton><CButton :loading="busy" @click="refund">Confirmar reembolso</CButton></template></CModal></div></template>
<script setup lang="ts">
import type {OnlinePayment} from '~/types/guestServices'
definePageMeta({middleware:['auth','receptionist']})
const {get,post,run,error,busy}=useOperations(),payments=ref<OnlinePayment[]>([]),selected=ref<OnlinePayment>(),message=ref('')
const states:Record<string,string>={pending:'Pendiente',paid:'Cobrado',expired:'Vencido',refunded:'Reembolsado',refund_pending:'Reembolso en proceso'}
const fetchPayments=async()=>{payments.value=(await get<OnlinePayment[]>('online-payments')).data||[]}
const load=()=>run(fetchPayments)
const refund=()=>run(async()=>{if(!selected.value)return;await post(`online-payments/${selected.value.id}/refund`,{});selected.value=undefined;message.value='Reembolso enviado. Su estado se actualizará al confirmarlo la pasarela.';await fetchPayments()})
onMounted(load)
</script>
